export function getDistrictMonthMedia(districtId: string, monthIndex: number): MonthlyMedia {
  const distData = TIMETABLE_MEDIA_MAP[districtId.toLowerCase()];
  if (distData && distData[monthIndex]) {
    return distData[monthIndex];
  }
  // Fallback to colombo if district not found
  const fallback = TIMETABLE_MEDIA_MAP['colombo'];
  return (fallback && fallback[monthIndex]) || { imageUrl: null, pdfUrl: null };
}
